import { config } from './config.js'
import { lookupSwap, listUnfinishedSwapsForAddress, SwapNotFound } from './meson.js'
import { extractCandidates, extractAddressCandidates } from './extract.js'
import { buildSwapEmbed, buildUnfinishedAddressEmbeds, buildSwapNotFoundMessage } from './render.js'
import { getTicket, rememberSwap } from './ticket-state.js'
import { watchSwap, detailsEmbed, syncFollowUps } from './watch.js'
import { canReply, isStaff, messageText, quietReply } from './discord-util.js'

// =============================================================================
//   Entry point
// =============================================================================

/**
 * MessageCreate entry point.
 * A ticket is a channel under a REPLY_CATEGORY_IDS category where the bot may post (canReply) — elsewhere it stays silent without looking anything up.
 * Filters to messages worth reading, then queues them so each ticket handles one message at a time — two quick pastes of the same swap cannot both get past the "already shown" check.
 */
export function onTicketMessage (message) {
  if (!canReply(message.channel)) return
  admitMessage(getTicket(message.channelId), message)
}

/**
 * Queue one ticket message if it is worth reading — the filter shared by live messages and those missed while the bot was down (recover.js).
 * Skips this bot's own messages and staff; other bots (Ticket Tool's form embed) only for the first AUTO_SCAN_MESSAGES.
 */
export function admitMessage (t, message) {
  if (message.author?.id === message.client.user.id) return
  // Staff paste IDs while investigating — those are not requests.
  if (isStaff(message.member)) return

  // Other bots (Ticket Tool's form embed) only matter at the start of a ticket; the user's own messages are read for the life of the ticket.
  const fromUser = !message.author?.bot
  if (!fromUser) {
    if (t.botMessagesSeen >= config.scanLimit) return
    t.botMessagesSeen++
  }

  queueMessage(t, message, fromUser, 1)
}

/** How often a message is handled in all when Meson errors (not "not found"): the first try plus TICKET_RETRIES. */
const MESSAGE_ATTEMPTS = config.ticketRetries + 1
const MESSAGE_RETRY_MS = config.ticketRetryMs

/**
 * Queue a message for its ticket.
 * If Meson errors out (down, HTML error page — after getJson's own quick retries), try the whole message again later rather than leave the ticket unanswered.
 * Safe to repeat: swaps already posted are known to the ticket and skipped.
 */
function queueMessage (t, message, fromUser, attempt) {
  t.queue = t.queue
    .then(() => handleTicketMessage(t, message, fromUser))
    .catch((err) => {
      const again = attempt < MESSAGE_ATTEMPTS
      console.error(`#${message.channel.name}: lookup failed (attempt ${attempt}/${MESSAGE_ATTEMPTS}` +
        `${again ? `, retrying in ${MESSAGE_RETRY_MS / 1000}s` : ', giving up'}) —`, err.message)
      if (again) setTimeout(() => queueMessage(t, message, fromUser, attempt + 1), MESSAGE_RETRY_MS)
    })
}

// =============================================================================
//   Message handling
// =============================================================================

/**
 * Look up every swap-shaped value in one message (priority order), post each new swap, then fall back to the wallet or a "couldn't find" reply.
 */
async function handleTicketMessage (t, message, fromUser) {
  const channel = message.channel
  const text = messageText(message)
  const swapCandidates = extractCandidates(text)
  // allowFallback: false — without it any sentence would "match" as an address.
  const address = extractAddressCandidates(text, { allowFallback: false })[0]

  // Candidates already known to belong to a shown swap are skipped unlooked-up.
  const fresh = swapCandidates.filter((c) => !t.known.has(c.toLowerCase()))
  let foundAny = swapCandidates.length > fresh.length
  const resolved = new Set()

  for (const query of fresh) {
    if (t.known.has(query.toLowerCase())) { foundAny = true; resolved.add(query); continue } // resolved via an earlier candidate
    let swap
    try {
      swap = await lookupSwap(query)
    } catch (err) {
      if (err instanceof SwapNotFound) continue
      throw err
    }
    foundAny = true
    resolved.add(query)
    const isNew = !t.swaps.some((e) => e.swapId === swap.swapId)
    if (isNew) await postSwap(t, message, swap, fromUser) // remembered only once actually shown
    rememberSwap(t, swap)
    t.known.add(query.toLowerCase())
    console.log(isNew
      ? `#${channel.name}: posted #${t.swaps.length} ${swap.swapId} (from ${query})`
      : `#${channel.name}: ${query} is ${swap.swapId}, already shown — ignored`)
  }
  const notFound = fresh.filter((q) => !resolved.has(q))

  // Wallet fallback: only when nothing above resolved and the ticket shows no swap yet (a wallet pasted after a swap is clutter). Once per address.
  const useWallet = Boolean(address) && !foundAny && !t.swaps.length && !t.addresses.has(address.toLowerCase())
  if (address && !useWallet) console.log(`#${channel.name}: wallet ${address} ignored (swap found or already handled)`)
  if (useWallet && await postWalletSwaps(t, message, address, fromUser ? notFound : [])) return

  // "Couldn't find" only for the user's own message (the form embed is full of Discord IDs and other hex-ish noise) and only if nothing else resolved — candidates are fallbacks for one another.
  if (fromUser && notFound.length && !foundAny) {
    await quietReply(message, { content: buildSwapNotFoundMessage(notFound) })
    console.log(`#${channel.name}: no swap for ${notFound.join(', ')} — told the user`)
  }
}

// =============================================================================
//   Posting
// =============================================================================

/**
 * Post a newly found swap — as a reply when the user pasted it mid-ticket, so it is clear what the bot is answering. When a second swap arrives, the first embed, its ⏳ and its closing message are re-rendered to show its "#1"; every earlier closing message also loses "ticket will be closed soon" while the new swap is open.
 */
async function postSwap (t, message, swap, fromUser) {
  const n = t.swaps.length + 1
  const embeds = [buildSwapEmbed(swap, { serial: n > 1 ? n : null, sourceNote: 'auto-detected from this ticket' })]
  const posted = fromUser ? await quietReply(message, { embeds }) : await message.channel.send({ embeds })
  // Registered only once posted, so a failed send leaves no half-made entry.
  const entry = { n, swapId: swap.swapId, message: posted, latest: swap }
  t.swaps.push(entry)

  if (n === 2) await t.swaps[0].message.edit({ embeds: [detailsEmbed(t, t.swaps[0])] }).catch(() => {})
  // Earlier swaps' ⏳ / closing message: "Swap #1" once there are two, and no "closed soon" while this one is open.
  for (const e of t.swaps.slice(0, -1)) await syncFollowUps(t, e)

  watchSwap(t, entry).catch((err) => console.error(`#${message.channel.name}: outcome post failed —`, err.message))
}

/**
 * List a wallet's swaps that are not finished (Done, Released or Cancelled), one embed per message (Discord's 6000-character cap covers all of a message's embeds).
 * `missed` = IDs the user pasted that did not resolve; the embed says so instead of a separate "couldn't find" reply.
 * @returns {Promise<boolean>} false if the address lookup failed (ticket noise)
 */
async function postWalletSwaps (t, message, address, missed) {
  let result
  try {
    result = await listUnfinishedSwapsForAddress(address) // limits: ADDRESS_* settings
  } catch (err) {
    // Meson down: rethrow so the whole message is retried (queueMessage).
    if (!err.rejected) throw err
    // Meson rejected it as an address — ticket noise, not a real request.
    t.addresses.add(address.toLowerCase())
    console.log(`#${message.channel.name}: address lookup failed for ${address} — ${err.message}`)
    return false
  }
  // Marked only once answered, so a retry after an outage still lists it.
  t.addresses.add(address.toLowerCase())
  const [first, ...rest] = buildUnfinishedAddressEmbeds(address, result, { sourceNote: 'auto-detected from this ticket', missed })
  if (message.author?.bot) await message.channel.send({ embeds: [first] })
  else await quietReply(message, { embeds: [first] })
  for (const embed of rest) await message.channel.send({ embeds: [embed] })
  console.log(`#${message.channel.name}: ${address} — ${result.swaps.length} unfinished of ${result.scanned} checked (${result.stoppedBy})`)
  return true
}
